import SwiftUI

/// A skin is a named visual identity for the app: a palette, a surface
/// treatment, and a type design. It is *not* a light/dark pair — every skin
/// carries both appearances (and high-contrast variants) in the asset catalog,
/// so the system's colour scheme keeps working inside any skin.
///
/// ## Where a skin's colours live
///
/// In `Shared/Assets.xcassets`, under `skin/<id>/…`, generated by
/// `design-system/color/generate_colorsets.py` from `palette-skins.json`
/// exactly like the default tokens. Each accessor below switches on `self` and
/// returns the Xcode-generated symbol for that skin — never a string lookup, so
/// a missing colorset is a compile error, and `ColorContrastTests` gates every
/// skin against the same floors as the default.
///
/// The default skin reads the un-namespaced tokens (`surface/card`,
/// `text/secondary`, `AccentColor`) — the catalog the app shipped with, untouched.
///
/// ## What a skin never touches
///
/// Graphs. The timeline spine, sparklines and PK charts read `series.color`
/// and `Color.primary` with their own opacities and never see `Theme`, so a
/// skin cannot restyle them. Per-substance identity colours (L3) and the L2
/// encoding scales (routes, dose tiers, phases) are likewise not a skin's to
/// change — only their surrounding chrome is.
///
/// Lives in `Shared/` so the widget and Live Activity targets can resolve the
/// active skin's colours from the same catalog; the store that *chooses* the
/// skin (`SkinStore`) is app-only.
enum Skin: String, CaseIterable, Identifiable, Sendable {
    /// The app's own look: soft pink light, hot pink dark, Liquid Glass.
    case piru
    /// ely.pink — the author's homepage. Night (plum-black, hot pink, lilac,
    /// mint) and pink (cream cards on a pink ground with near-black edges).
    /// Solid edged cards with hard offset shadows; nothing tilts.
    case elyPink

    var id: String { rawValue }

    /// Picker name. Localized like every user-facing string.
    var displayName: LocalizedStringResource {
        switch self {
        case .piru: "Piru"
        case .elyPink: "ely.pink"
        }
    }

    /// One line under the name in the picker.
    var tagline: LocalizedStringResource {
        switch self {
        case .piru: "Soft pink, hot pink, liquid glass"
        case .elyPink: "Night and pink, stickers and pixels"
        }
    }

    // MARK: - Current

    /// The skin the app is showing, readable from `Shared/` code that cannot
    /// see `SkinStore`. The app installs a provider that reads the observable
    /// store (so reads inside a `body` are tracked); before that, and in the
    /// extensions, it falls back to the persisted choice.
    nonisolated static var current: Skin { currentProvider() }

    /// Replaced once by `SkinStore.activate()` at launch; read on the main
    /// thread from view bodies. `nonisolated(unsafe)` because the members of
    /// this `Sendable` enum are nonisolated and the write happens before any
    /// view exists.
    nonisolated(unsafe) static var currentProvider: @Sendable () -> Skin = { SkinDefaults.storedSkin() }

    /// Label colour on an ``accentMark`` fill (buttons, tab stickers). Night
    /// ely.pink puts near-black ink on hot pink (6.4:1); pink mode uses white
    /// on the darker text accent. The default skin's white-on-accent is the
    /// system's own choice for `.glassProminent`.
    var onAccent: Color {
        switch self {
        case .piru: .white
        case .elyPink: .Skin.Elypink.Accent.on
        }
    }

    // MARK: - Palette

    /// Brand accent and control tint. **Text-safe** in every skin: the app uses
    /// one token for both copy and marks, so where a skin's vivid mark colour
    /// fails as small text (ely.pink's hot pink on cream, 2.9:1) this is the
    /// darker `accent/text` twin and ``accentMark`` carries the vivid one.
    var accent: Color {
        switch self {
        case .piru: .accent
        case .elyPink: .Skin.Elypink.Accent.text
        }
    }

    /// The vivid accent for standalone marks: rings, glows, selection fills
    /// under white text. Gated at the 3:1 non-text floor, never used as copy.
    var accentMark: Color {
        switch self {
        case .piru: .accent
        case .elyPink: .Skin.Elypink.Accent.mark
        }
    }

    /// De-emphasized body text. Gated AA 4.5:1 on `cardBackground`.
    var secondaryLabel: Color {
        switch self {
        case .piru: .Text.secondary
        case .elyPink: .Skin.Elypink.Text.secondary
        }
    }

    /// Page backdrop.
    var background: Color {
        switch self {
        case .piru: .Surface.background
        case .elyPink: .Skin.Elypink.Surface.background
        }
    }

    /// Card / raised surface fill.
    var cardBackground: Color {
        switch self {
        case .piru: .Surface.card
        case .elyPink: .Skin.Elypink.Surface.card
        }
    }

    /// Text-field and other input fills.
    var inputBackground: Color {
        switch self {
        case .piru: .Surface.input
        case .elyPink: .Skin.Elypink.Surface.input
        }
    }

    /// Eyebrows, section labels, sticker shadows — the skin's "wine". The
    /// default skin has no such role and uses secondary text.
    var eyebrow: Color {
        switch self {
        case .piru: .Text.secondary
        case .elyPink: .Skin.Elypink.eyebrow
        }
    }

    /// Status colours. Skins may re-seed the L1 ladder (ely.pink maps its own
    /// mint / gold / blue and a danger red the site never had); the roles and
    /// the `text` / `accent` split are fixed by the design system.
    func semantic(_ role: SemanticRole, _ variant: SemanticVariant) -> Color {
        switch (self, role, variant) {
        case (.piru, .danger, .text): .Semantic.Danger.text
        case (.piru, .danger, .accent): .Semantic.Danger.accent
        case (.piru, .caution, .text): .Semantic.Caution.text
        case (.piru, .caution, .accent): .Semantic.Caution.accent
        case (.piru, .success, .text): .Semantic.Success.text
        case (.piru, .success, .accent): .Semantic.Success.accent
        case (.piru, .info, .text): .Semantic.Info.text
        case (.piru, .info, .accent): .Semantic.Info.accent
        case (.elyPink, .danger, .text): .Skin.Elypink.Semantic.Danger.text
        case (.elyPink, .danger, .accent): .Skin.Elypink.Semantic.Danger.accent
        case (.elyPink, .caution, .text): .Skin.Elypink.Semantic.Caution.text
        case (.elyPink, .caution, .accent): .Skin.Elypink.Semantic.Caution.accent
        case (.elyPink, .success, .text): .Skin.Elypink.Semantic.Success.text
        case (.elyPink, .success, .accent): .Skin.Elypink.Semantic.Success.accent
        case (.elyPink, .info, .text): .Skin.Elypink.Semantic.Info.text
        case (.elyPink, .info, .accent): .Skin.Elypink.Semantic.Info.accent
        }
    }

    // MARK: - Surface treatment

    /// How cards and capsules are drawn. The default skin keeps the app's
    /// scheme-adaptive material; an edged skin draws a solid fill with a stroke
    /// and a hard offset shadow instead of any material.
    var surface: SkinSurface {
        switch self {
        case .piru: .glass
        case .elyPink: .edged(
            stroke: .Skin.Elypink.stroke,
            strokeWidth: 2.5,
            shadow: .Skin.Elypink.shadow,
            shadowOffset: CGSize(width: 3, height: 3),
        )
        }
    }

    /// A fixed card radius for skins whose cards are drawn objects rather than
    /// system-concentric surfaces. `nil` keeps the caller's (concentric) radius.
    var cardCornerRadius: CGFloat? {
        switch self {
        case .piru: nil
        case .elyPink: 12
        }
    }

    // MARK: - Type

    /// Applied once at the root. `nil` keeps the system default design; this
    /// reshapes every semantic text style in the app without touching call
    /// sites. Custom families are the typography layer's job, not this one's.
    var fontDesign: Font.Design? {
        switch self {
        case .piru: nil
        case .elyPink: .rounded
        }
    }
}

/// The L1 status roles. A closed set — see `design-system/README.md`.
enum SemanticRole: CaseIterable, Sendable {
    case danger, caution, success, info
}

/// `text` is small copy (gated 4.5:1); `accent` is a standalone mark (3:1).
enum SemanticVariant: CaseIterable, Sendable {
    case text, accent
}

/// The card treatment a skin asks for. See ``ThemedBackground``.
enum SkinSurface: Equatable, Sendable {
    /// `.ultraThinMaterial` in light, the skin's `cardBackground` in dark —
    /// the treatment the app shipped with.
    case glass
    /// Solid `cardBackground` in both schemes, a `strokeWidth` border in
    /// `stroke`, and a hard (unblurred) shadow of `shadow` offset by `shadowOffset`.
    case edged(stroke: Color, strokeWidth: CGFloat, shadow: Color, shadowOffset: CGSize)
}

/// The user's light/dark override. `system` defers to iOS.
enum SkinColorScheme: String, CaseIterable, Identifiable, Sendable {
    case system, light, dark

    var id: String { rawValue }

    /// Distinct from the dose-tier key `"Light"` (轻度), which is a different word.
    var displayName: LocalizedStringResource {
        switch self {
        case .system: "Follow System"
        case .light: "Light Mode"
        case .dark: "Dark Mode"
        }
    }

    /// What to hand `preferredColorScheme`. `nil` means follow the system.
    var colorScheme: ColorScheme? {
        switch self {
        case .system: nil
        case .light: .light
        case .dark: .dark
        }
    }
}

/// UserDefaults keys for the skin preference. One source of truth so the app's
/// `SkinStore` and the extensions read the same choice. Stored in the app group
/// suite so the widget and Live Activity can honour it.
nonisolated enum SkinDefaults {
    static let suite = "group.dev.yumeji.piru"
    static let skinKey = "skin"
    static let colorSchemeKey = "skinColorScheme"
    static let skinDefault: Skin = .piru
    static let colorSchemeDefault: SkinColorScheme = .system

    /// The persisted skin, for targets without a `SkinStore` (widgets). Falls
    /// back to the default when the stored value names a skin this build lacks.
    static func storedSkin(in defaults: UserDefaults? = UserDefaults(suiteName: suite)) -> Skin {
        guard let raw = defaults?.string(forKey: skinKey), let skin = Skin(rawValue: raw) else {
            return skinDefault
        }
        return skin
    }
}
